changes.msgid:
--time=WORD
   select which timestamp used to display or sort;
     access time (-u): atime, access, use;
     metadata change time (-c): ctime, status;
     modified time (default): mtime, modification;
     birth time: birth, creation;
   with -l, WORD determines which time to show;
   with --sort=time, sort by WORD (newest first)

changes.before:
--time=ORD
   välj vilka tidsstämplar som används för att visa eller sortera:
     åtkomsttid (-u): atime, access, use;
     metadataändringstid (-c): ctime, status;
     modifieringstid (standard); mtime, modification;
     födelsetid: birth, creation;
   med -l avgör ORD vilken tid att visa;
   med --sort=time, sortera enligt ORD (nyast först)

changes.after:
--time=ORD
   välj vilken tidsstämpel som används för att visa eller sortera:
     åtkomsttid (-u): atime, access, use;
     metadataändringstid (-c): ctime, status;
     modifieringstid (standard): mtime, modification;
     skapandetid: birth, creation;
   med -l avgör ORD vilken tid att visa;
   med --sort=time, sortera enligt ORD (nyast först)

-p, --parents
       inget fel om katalogen finns, skapa föräldrakataloger vid behov;
       föräldrakatalogernas rättigheter påverkas inte av någon -m-flagga

changes.msgid:
--field=FIELDS
   replace the numbers in these input fields (default=1);
   see FIELDS below for details

changes.before:
--field=FÄLT
   ersätt talen i dessa indatarader (standard är 1);
   se FÄLT nedan för detaljer

changes.after:
--field=FÄLT
   ersätt talen i dessa indatafält (standard är 1);
   se FÄLT nedan för detaljer

changes.msgid:
--padding=N
   pad the output to N characters;
   positive N will right-align, negative N will left-align;
   padding is ignored if the output is wider than N;
   the default is to automatically pad if a whitespace is found

changes.before:
--padding=N
   fyll ut utdata till N tecken;
   positivt N kommer högerjustera, negativt N kommer vänsterjustera;
   utfyllnad ignoreras om utdata är bredare än N;
   standard är att automatiskt fylla ut om en blank finns

changes.after:
--padding=N
   fyll ut utdata till N tecken;
   positivt N högerjusterar, negativt N vänsterjusterar;
   utfyllnad ignoreras om utdata är bredare än N;
   standard är att automatiskt fylla ut om en blank finns

changes.before:
--endian={big|little}
   byt plats på indatabyte:ar enligt angiven
                          byteordning

changes.msgid:
-p, --parents
       remove DIRECTORY and its ancestors;
       e.g., 'rmdir -p a/b' is similar to 'rmdir a/b a'

