changes.msgid:
-f, --follow[={name|descriptor}]
       output appended data as the file grows;
       an absent option argument means 'descriptor'

changes.before:
-f, --follow[={namn|filidentifierare}]
       skriv ut nya rader i takt med att filen växer;
       ett utelämnat argument betyder ”filidentifierare”

changes.after:
-f, --follow[={name|descriptor}]
       skriv ut tillagda data i takt med att filen växer;
       ett utelämnat argument betyder ”descriptor”

changes.msgid:
--group[=METHOD]
   show all items, separating groups with an empty line;
   METHOD={separate(default),prepend,append,both}

